videoUrl.iframeSelector:
(function(){
function mediaOk(u){if(typeof u!='string'||u.indexOf('http')!=0)return '';if(u.indexOf('.m3u8')>=0||u.indexOf('.mp4')>=0||u.indexOf('.flv')>=0)return u;return '';}
function perfM3u8(){try{var es=performance.getEntriesByType('resource');for(var i=es.length-1;i>=0;i--){var n=es[i].name;if(n&&n.indexOf('http')==0&&n.indexOf('.m3u8')>=0)return n;}}catch(e){}return '';}
function syncTry(){var f=document.querySelector('iframe#video');var r=mediaOk(f&&f.getAttribute('src'));if(!r){var v=document.querySelector('#artplayer video, video');if(v){r=mediaOk(v.currentSrc||v.src);}}if(!r){r=perfM3u8();}return r;}
var R=syncTry();
if(R){return R;}
function post(u){try{window.animeBridge.onLink(u);}catch(e){}}
if(!window.__animeHook){
window.__animeHook=1;
try{var oo=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(m,u){try{var s=String(u);if(s.indexOf('http')==0&&s.indexOf('.m3u8')>=0){post(s);}}catch(e){}return oo.apply(this,arguments);};}catch(e){}
try{var of=window.fetch;window.fetch=function(){try{var a=arguments[0];var s=(typeof a=='string')?a:((a&&a.url)||'');if(s&&s.indexOf('http')==0&&s.indexOf('.m3u8')>=0){post(s);}}catch(e){}return of.apply(this,arguments);};}catch(e){}
var iv=setInterval(function(){var r=syncTry();if(r){clearInterval(iv);post(r);return;}if(document.querySelector('#error')){clearInterval(iv);post('ERR_SITE_BADRESP');}},500);
setTimeout(function(){clearInterval(iv);},30000);
}
return 'PENDING';
})()
